{
  "threat_id": "DF-BLEPAIR-I",
  "title": "Unencrypted BLE Pairing Traffic Capture",
  "stride": "I",
  "assets_affected": [
    "DFD:DF-BLEPAIR"
  ],
  "existing_controls": [
    {
      "id": "CTRL:tls-1-0-for-encrypted-data-in-transit-legacy",
      "description": "TLS 1.0 for encrypted data-in-transit (legacy)",
      "kind": "legacy"
    }
  ],
  "gap_analysis": [],
  "cvss_v31": {
    "vector": "CVSS:3.1/AV:A/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:N",
    "base_score": 8.1,
    "severity": "High"
  },
  "residual_risk": "Medium",
  "residual_risk_reason": "Implementing BLE Secure Connections will mitigate the risk, but potential vulnerabilities in BLE stack remain.",
  "proposed_controls": [
    {
      "id": "CTRL:PROPOSED:ble-secure-connections",
      "description": "Implement BLE Secure Connections with LE Secure Connections pairing to ensure encryption during the pairing process.",
      "kind": "proposed"
    }
  ],
  "proposed_doc_changes": [
    {
      "doc": "SDS.md",
      "action": "add",
      "item_id": "SDS-SEC-NEW-01",
      "body": "Implement BLE Secure Connections to encrypt the pairing process and protect against key interception."
    }
  ],
  "proposed_code_changes": [
    {
      "path": "firmware/app_mcu/ble/ble_pairing.c",
      "line": 42,
      "action": "modify",
      "hunk": "/* Enable LE Secure Connections for BLE pairing */\nble_enable_secure_connections();"
    }
  ],
  "priority": "P1",
  "effort_engineer_weeks": 1.0,
  "narrative": "The BLE pairing process currently lacks encryption, allowing adversaries to intercept the LTK derivation process. Implementing BLE Secure Connections will encrypt the pairing process, mitigating the risk of key interception and replay attacks."
}

