{
  "threat_id": "DF-SPICONFIG-D",
  "title": "SPI bus starvation attack",
  "stride": "D",
  "assets_affected": [
    "DFD:DF-SPICONFIG"
  ],
  "existing_controls": [
    {
      "id": "CTRL:lightweight-range-check-at-safety-mcu",
      "description": "Lightweight range check at Safety MCU",
      "kind": "legacy"
    }
  ],
  "gap_analysis": [
    {
      "clause_id": "FDA-2023-V.B.9",
      "verdict": "missing",
      "quote": "Debug interfaces (JTAG, UART, SWD) and service ports shall be disabled or protected against unauthorized access in production configurations.",
      "reason": "No existing control addresses the requirement for protecting debug interfaces against unauthorized access."
    },
    {
      "clause_id": "FDA-2023-V.B.7",
      "verdict": "missing",
      "quote": "The device shall implement a secure boot chain such that only cryptographically verified firmware may execute after power-on.",
      "reason": "No existing control ensures a secure boot chain with cryptographic verification of firmware."
    },
    {
      "clause_id": "FDA-2023-V.B.3",
      "verdict": "missing",
      "quote": "Integrity-only checks such as CRC or non-cryptographic hashes are insufficient.",
      "reason": "The existing control uses CRC-16-CCITT, which does not meet the modern requirement for cryptographic authenticity verification."
    },
    {
      "clause_id": "FDA-2023-V.A.1",
      "verdict": "missing",
      "quote": "The device manufacturer shall document a Secure Product Development Framework (SPDF) integrating cybersecurity considerations throughout the product lifecycle.",
      "reason": "No existing control addresses the need for a documented Secure Product Development Framework."
    },
    {
      "clause_id": "NIST-800-193-5.2",
      "verdict": "missing",
      "quote": "The platform shall detect corruption of firmware code, firmware data, and critical platform configuration.",
      "reason": "No existing control provides for detection of firmware corruption or integrity verification."
    },
    {
      "clause_id": "AAMI-TIR57-6.3.2",
      "verdict": "present",
      "quote": "For each security risk that exceeds the acceptable level, the manufacturer shall specify and implement risk-control measures.",
      "reason": "The existing control for lightweight range checks can be seen as a risk-control measure for the identified threat."
    }
  ],
  "cvss_v31": {
    "vector": "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:C/C:N/I:L/A:H",
    "base_score": 9.1,
    "severity": "Critical"
  },
  "residual_risk": "Medium",
  "residual_risk_reason": "Implementing cryptographic verification and rate limiting reduces risk to Medium.",
  "proposed_controls": [
    {
      "id": "CTRL:PROPOSED:cryptographic-verification",
      "description": "Implement cryptographic verification for SPI commands using HMAC-SHA256.",
      "kind": "proposed"
    },
    {
      "id": "CTRL:PROPOSED:rate-limiting",
      "description": "Introduce rate limiting on SPI command processing to prevent flooding.",
      "kind": "proposed"
    }
  ],
  "proposed_doc_changes": [
    {
      "doc": "SDS.md",
      "action": "add",
      "item_id": "SDS-SEC-NEW-01",
      "body": "Implement cryptographic verification for SPI commands using HMAC-SHA256 to ensure authenticity and integrity."
    }
  ],
  "proposed_code_changes": [
    {
      "path": "firmware/safety_mcu/spi_slave.c",
      "line": 100,
      "action": "modify",
      "hunk": "void process_spi_command() {\n  if (!verify_hmac_sha256(command)) {\n    log_error(\"Invalid HMAC\");\n    return;\n  }\n  // Existing command processing logic\n}"
    },
    {
      "path": "firmware/safety_mcu/spi_slave.c",
      "line": 120,
      "action": "modify",
      "hunk": "void process_spi_command() {\n  static int command_count = 0;\n  static time_t last_reset = 0;\n  if (time(NULL) - last_reset > 1) {\n    command_count = 0;\n    last_reset = time(NULL);\n  }\n  if (command_count++ > MAX_COMMANDS_PER_SECOND) {\n    log_error(\"Rate limit exceeded\");\n    return;\n  }\n  // Existing command processing logic\n}"
    }
  ],
  "priority": "P0",
  "effort_engineer_weeks": 2.0,
  "narrative": "The SPI bus is vulnerable to starvation attacks due to lack of cryptographic verification and rate limiting. Implementing HMAC-SHA256 for command verification and introducing rate limiting will mitigate this threat, reducing the risk of device crashes or missed safety-critical updates."
}

