      "clause_id": "FDA-2023-V.B.7",
      "verdict": "missing",
      "quote": "The device shall implement a secure boot chain such that only cryptographically verified firmware may execute after power-on. Runtime integrity monitoring of critical safety code shall detect and respond to unauthorized modification.",
      "reason": "The existing control does not implement secure boot or integrity monitoring for firmware."
    },
    {
      "clause_id": "FDA-2023-V.B.6",
      "verdict": "missing",
      "quote": "Bluetooth, Wi-Fi, and other wireless links shall be paired using authenticated, encrypted mechanisms. Just Works or unauthenticated pairing shall not be used for links that carry patient data or control commands. Bluetooth Low Energy shall use LE Secure Connections with numeric comparison or out-of-band authentication.",
      "reason": "The existing control does not address wireless pairing or link security mechanisms."
    },
    {
      "clause_id": "NIST-800-193-4.3",
      "verdict": "missing",
      "quote": "The platform shall include a Root of Trust for Update (RTU) — immutable or protected code and data that authenticate firmware updates. The RTU shall be protected against unauthorized modification for the life of the platform.",
