{
  "threat_id": "DF-OTA-I",
  "title": "Exfiltrating OTA Manifest Data",
  "stride": "I",
  "assets_affected": [
    "DFD:DF-OTA"
  ],
  "existing_controls": [],
  "gap_analysis": [
    {
      "clause_id": "FDA-2023-V.B.3",
      "verdict": "missing",
      "quote": "Firmware images and any over-the-air or in-field update artifacts shall be protected with cryptographic authenticity verification using signature schemes based on modern asymmetric cryptography. Integrity-only checks such as CRC or non-cryptographic hashes are insufficient. The device shall refuse to install any firmware or update whose signature cannot be verified against a manufacturer-controlle",
      "reason": "No existing controls address the requirement for cryptographic authenticity verification for firmware updates."
    },
    {
      "clause_id": "NIST-800-193-4.2",
      "verdict": "missing",
      "quote": "All firmware updates shall be authenticated by verifying a digital signature over the update image using a public key rooted in a trusted key store. Authentication shall occur before the update is applied. Rollback protection shall prevent installation of older, vulnerable versions unless explicitly authorized.",
      "reason": "No existing controls provide the necessary authentication for firmware updates via digital signatures."
    },
    {
      "clause_id": "FDA-2023-V.B.4",
      "verdict": "missing",
      "quote": "Patient health information (PHI) and sensitive configuration data shall be protected in confidentiality both at rest on the device and during transmission over any network interface. Encryption shall use current, standards-based algorithms and appropriate key management.",
      "reason": "No existing controls ensure confidentiality of sensitive data at rest or in transit."
    },
    {
      "clause_id": "NIST-800-193-5.2",
      "verdict": "missing",
      "quote": "The platform shall detect corruption of firmware code, firmware data, and critical platform configuration. Detection may occur at boot time, at runtime, or through periodic integrity verification, and shall be reported to a management interface.",
      "reason": "No existing controls are in place for detecting corruption of firmware or critical configurations."
    },
    {
      "clause_id": "NIST-800-193-4.3",
      "verdict": "missing",
      "quote": "The platform shall include a Root of Trust for Update (RTU) — immutable or protected code and data that authenticate firmware updates. The RTU shall be protected against unauthorized modification for the life of the platform.",
      "reason": "No existing controls establish a Root of Trust for firmware updates."
    },
    {
      "clause_id": "FDA-2023-V.B.8",
      "verdict": "missing",
      "quote": "The device shall log security-relevant events including authentication attempts, privileged operations, configuration changes, and update activities. Logs shall carry tamper-evident properties and be exportable in a machine-readable format.",
      "reason": "No existing controls provide for logging of security-relevant events as required."
    }
  ],
  "cvss_v31": {
    "vector": "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:N",
    "base_score": 8.2,
    "severity": "High"
  },
  "residual_risk": "Medium",
  "residual_risk_reason": "Implementing encryption and authentication reduces risk, but residual risk remains due to potential implementation flaws.",
  "proposed_controls": [
    {
      "id": "CTRL:PROPOSED:tls_upgrade",
      "description": "Upgrade TLS to version 1.2 or higher with certificate pinning for OTA manifest retrieval.",
      "kind": "proposed"
    },
    {
      "id": "CTRL:PROPOSED:encrypt_storage",
      "description": "Encrypt manifest data at rest using AES-256.",
      "kind": "proposed"
    }
  ],
  "proposed_doc_changes": [
    {
      "doc": "SDS.md",
      "action": "add",
      "item_id": "SDS-SEC-NEW-01",
      "body": "The system shall use TLS 1.2 or higher with certificate pinning for all OTA manifest data transmissions to ensure confidentiality and integrity."
    },
    {
      "doc": "SDS.md",
      "action": "add",
      "item_id": "SDS-SEC-NEW-02",
      "body": "Manifest data stored on the device shall be encrypted using AES-256 to protect confidentiality at rest."
    }
  ],
  "proposed_code_changes": [
    {
      "path": "firmware/app_mcu/network/tls_config.c",
      "line": 45,
      "action": "modify",
      "hunk": "tls_config.version = TLS_VERSION_1_2;\ntls_config.certificate_pinning = ENABLED;"
    },
    {
      "path": "firmware/app_mcu/ota/manifest_parser.c",
      "line": 120,
      "action": "modify",
      "hunk": "encrypt_data(manifest_data, AES_256_KEY);"
    }
  ],
  "priority": "P1",
  "effort_engineer_weeks": 2.0,
  "narrative": "The OTA manifest data is vulnerable to interception due to outdated TLS and lack of encryption at rest. Upgrading to TLS 1.2 with certificate pinning and encrypting stored data will mitigate these risks."
}

