{
  "threat_id": "DF-SPIFW-T",
  "title": "Spoofed SPI firmware chunk injection",
  "stride": "T",
  "assets_affected": [
    "DFD:DF-SPIFW"
  ],
  "existing_controls": [
    {
      "id": "CTRL:crc-16-ccitt-checksum-on-each-chunk",
      "description": "CRC-16-CCITT checksum on each chunk",
      "kind": "legacy"
    }
  ],
  "gap_analysis": [],
  "cvss_v31": {
    "vector": "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
    "base_score": 9.8,
    "severity": "Critical"
  },
  "residual_risk": "Medium",
  "residual_risk_reason": "Implementing cryptographic integrity checks reduces risk but does not eliminate it entirely.",
  "proposed_controls": [
    {
      "id": "CTRL:PROPOSED:sha256-integrity-check",
      "description": "Implement SHA-256 integrity check for OTA firmware chunks.",
      "kind": "proposed"
    }
  ],
  "proposed_doc_changes": [
    {
      "doc": "SDS.md",
      "action": "add",
      "item_id": "SDS-SEC-NEW-01",
      "body": "Introduce SHA-256 integrity checks for OTA firmware updates to ensure authenticity and integrity of firmware chunks."
    }
  ],
  "proposed_code_changes": [
    {
      "path": "firmware/app_mcu/ota/install_handler.c",
      "line": 45,
      "action": "modify",
      "hunk": "/* Add SHA-256 integrity check */\n#include <sha256.h>\n\nbool verify_firmware_chunk(const uint8_t *chunk, size_t size, const uint8_t *expected_hash) {\n    uint8_t hash[32];\n    sha256(chunk, size, hash);\n    return memcmp(hash, expected_hash, 32) == 0;\n}"
    }
  ],
  "priority": "P0",
  "effort_engineer_weeks": 1.0,
  "narrative": "The threat of spoofed SPI firmware chunk injection is critical due to the lack of robust integrity checks. Implementing SHA-256 integrity checks for OTA firmware updates will significantly enhance security by ensuring the authenticity and integrity of firmware chunks."
}

