{
  "threat_id": "DS-BOOT-I",
  "title": "Boot flag leakage via BLE data stream",
  "stride": "I",
  "assets_affected": [
    "DFD:DS-BOOT"
  ],
  "existing_controls": [
    {
      "id": "CTRL:crc-16-32-checksums-on-ble-packets-no-signatures",
      "description": "CRC-16/32 checksums on BLE packets (no signatures)",
      "kind": "legacy"
    }
  ],
  "gap_analysis": [
    {
      "clause_id": "FDA-2023-V.B.6",
      "verdict": "missing",
      "quote": "Bluetooth, Wi-Fi, and other wireless links shall be paired using authenticated, encrypted mechanisms. Just Works or unauthenticated pairing shall not be used for links that carry patient data or control commands. Bluetooth Low Energy shall use LE Secure Connections with numeric comparison or out-of-band authentication.",
      "reason": "The existing control does not address the requirement for authenticated and encrypted pairing mechanisms, which is critical for patient data security."
    },
    {
      "clause_id": "FDA-2023-V.B.7",
      "verdict": "missing",
      "quote": "The device shall implement a secure boot chain such that only cryptographically verified firmware may execute after power-on. Runtime integrity monitoring of critical safety code shall detect and respond to unauthorized modification.",
      "reason": "No existing control addresses the need for a secure boot chain with cryptographic verification, which is essential for preventing unauthorized firmware execution."
    },
    {
      "clause_id": "NIST-800-193-5.2",
      "verdict": "missing",
      "quote": "The platform shall detect corruption of firmware code, firmware data, and critical platform configuration. Detection may occur at boot time, at runtime, or through periodic integrity verification, and shall be reported to a management interface.",
      "reason": "There are no controls in place that provide the necessary detection of firmware corruption or integrity verification as required by this clause."
    },
    {
      "clause_id": "FDA-2023-V.B.9",
      "verdict": "missing",
      "quote": "Debug interfaces (JTAG, UART, SWD) and service ports shall be disabled or protected against unauthorized access in production configurations. Where a service port is required, access shall be gated by strong authentication and shall be auditable.",
      "reason": "The existing controls do not address the hardening of physical ports or debug interfaces against unauthorized access."
    },
    {
      "clause_id": "FDA-2023-V.B.3",
      "verdict": "partial",
      "quote": "Firmware images and any over-the-air or in-field update artifacts shall be protected with cryptographic authenticity verification using signature schemes based on modern asymmetric cryptography. Integrity-only checks such as CRC or non-cryptographic hashes are insufficient. The device shall refuse to install any firmware or update whose signature cannot be verified against a manufacturer-controlle",
      "reason": "The existing control uses CRC-16/32 checksums, which do not meet the modern requirement for cryptographic authenticity verification."
    },
    {
      "clause_id": "FDA-2023-V.B.8",
      "verdict": "missing",
      "quote": "The device shall log security-relevant events including authentication attempts, privileged operations, configuration changes, and update activities. Logs shall carry tamper-evident properties and be exportable in a machine-readable format.",
      "reason": "There are no existing controls that address the logging of security-relevant events or ensure tamper-evident properties."
    }
  ],
  "cvss_v31": {
    "vector": "CVSS:3.1/AV:A/AC:L/PR:N/UI:N/S:U/C:H/I:N/A:N",
    "base_score": 6.5,
    "severity": "Medium"
  },
  "residual_risk": "Low",
  "residual_risk_reason": "Implementing BLE LE Secure Connections and secure boot will mitigate the risk of data leakage and unauthorized firmware execution.",
  "proposed_controls": [
    {
      "id": "CTRL:PROPOSED:ble-le-secure-connections",
      "description": "Implement BLE LE Secure Connections with numeric comparison or out-of-band authentication.",
      "kind": "proposed"
    },
    {
      "id": "CTRL:PROPOSED:secure-boot",
      "description": "Implement a secure boot chain with cryptographic verification of firmware.",
      "kind": "proposed"
    }
  ],
  "proposed_doc_changes": [
    {
      "doc": "SDS.md",
      "action": "add",
      "item_id": "SDS-SEC-NEW-01",
      "body": "The system shall use BLE LE Secure Connections with numeric comparison or out-of-band authentication to ensure secure pairing."
    },
    {
      "doc": "SDS.md",
      "action": "add",
      "item_id": "SDS-SEC-NEW-02",
      "body": "The system shall implement a secure boot chain to ensure only cryptographically verified firmware is executed."
    }
  ],
  "proposed_code_changes": [
    {
      "path": "firmware/app_mcu/ble/ble_pairing.c",
      "line": 10,
      "action": "modify",
      "hunk": "void setup_ble_pairing() {\n    // Implement LE Secure Connections\n    ble_enable_secure_connections();\n    // Additional pairing setup\n}"
    },
    {
      "path": "firmware/app_mcu/boot/loader.c",
      "line": 15,
      "action": "modify",
      "hunk": "void bootloader_init() {\n    // Implement secure boot verification\n    verify_firmware_signature();\n    // Additional bootloader initialization\n}"
    }
  ],
  "priority": "P2",
  "effort_engineer_weeks": 2.0,
  "narrative": "The threat involves leakage of boot flag information via BLE due to insecure pairing. Implementing BLE LE Secure Connections and a secure boot chain will mitigate this risk by ensuring encrypted communication and verified firmware execution."
}

