{
  "threat_id": "P-EMR-I",
  "title": "EMR Credential Exposure via Plaintext",
  "stride": "I",
  "assets_affected": [
    "DFD:P-EMR"
  ],
  "existing_controls": [
    {
      "id": "CTRL:physical-protection-only-no-network-encryption-for-credentials",
      "description": "Physical protection only (no network encryption for credentials)",
      "kind": "legacy"
    }
  ],
  "gap_analysis": [
    {
      "clause_id": "FDA-2023-V.B.6",
      "verdict": "missing",
      "quote": "Bluetooth, Wi-Fi, and other wireless links shall be paired using authenticated, encrypted mechanisms. Just Works or unauthenticated pairing shall not be used for links that carry patient data or control commands. Bluetooth Low Energy shall use LE Secure Connections with numeric comparison or out-of-band authentication.",
      "reason": "No existing control addresses the requirement for authenticated and encrypted wireless pairing mechanisms."
    },
    {
      "clause_id": "FDA-2023-V.B.4",
      "verdict": "missing",
      "quote": "Patient health information (PHI) and sensitive configuration data shall be protected in confidentiality both at rest on the device and during transmission over any network interface. Encryption shall use current, standards-based algorithms and appropriate key management.",
      "reason": "Existing control does not provide any encryption for data in transit, which is required by this clause."
    },
    {
      "clause_id": "FDA-2023-V.B.2",
      "verdict": "missing",
      "quote": "The device shall implement role-based authorization such that users and services are granted only the minimum privileges required for their function (principle of least privilege). Administrative functions shall be separated from clinical use.",
      "reason": "No existing control addresses role-based authorization or the principle of least privilege."
    },
    {
      "clause_id": "FDA-2023-V.B.9",
      "verdict": "missing",
      "quote": "Debug interfaces (JTAG, UART, SWD) and service ports shall be disabled or protected against unauthorized access in production configurations. Where a service port is required, access shall be gated by strong authentication and shall be auditable.",
      "reason": "Existing control does not address the hardening of debug interfaces or service ports."
    },
    {
      "clause_id": "FDA-2023-V.B.1",
      "verdict": "partial",
      "quote": "The device shall enforce identity authentication for all human users and for services interacting with the device. Default or shared credentials shall not be permitted for production deployment. Password complexity and rotation policies shall be enforced.",
      "reason": "Existing control mentions physical protection but does not enforce the prohibition of default/shared credentials."
    },
    {
      "clause_id": "FDA-2023-V.B.5",
      "verdict": "missing",
      "quote": "Network communications shall use transport-layer encryption (TLS 1.2 or later) with mutual authentication where feasible, and with certificate validation including hostname verification and pinning to trusted certificate authorities appropriate for the deployment context.",
      "reason": "No existing control provides transport-layer encryption or meets the TLS 1.2+ requirement."
    }
  ],
  "cvss_v31": {
    "vector": "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:N",
    "base_score": 8.1,
    "severity": "High"
  },
  "residual_risk": "Medium",
  "residual_risk_reason": "Implementing encryption and authentication will reduce exposure but some risk remains due to potential implementation flaws.",
  "proposed_controls": [
    {
      "id": "CTRL:PROPOSED:tls-encryption",
      "description": "Implement TLS 1.2+ for all network communications to ensure data confidentiality and integrity.",
      "kind": "proposed"
    },
    {
      "id": "CTRL:PROPOSED:ble-secure-connections",
      "description": "Use BLE LE Secure Connections with numeric comparison for pairing.",
      "kind": "proposed"
    },
    {
      "id": "CTRL:PROPOSED:role-based-auth",
      "description": "Implement role-based authorization to enforce the principle of least privilege.",
      "kind": "proposed"
    }
  ],
  "proposed_doc_changes": [
    {
      "doc": "SRS.md",
      "action": "add",
      "item_id": "SRS-SEC-NEW-01",
      "body": "The system shall use TLS 1.2 or later for all network communications to protect data in transit."
    },
    {
      "doc": "SRS.md",
      "action": "add",
      "item_id": "SRS-SEC-NEW-02",
      "body": "The system shall implement BLE LE Secure Connections with numeric comparison for secure pairing."
    },
    {
      "doc": "SRS.md",
      "action": "add",
      "item_id": "SRS-SEC-NEW-03",
      "body": "The system shall implement role-based authorization to ensure users and services have the minimum necessary privileges."
    }
  ],
