{
  "threat_id": "DF-SPIVITALS-T",
  "title": "Spoofed Vital Sign Frames via SPI",
  "stride": "T",
  "assets_affected": [
    "DFD:DF-SPIVITALS"
  ],
  "existing_controls": [
    {
      "id": "CTRL:crc-16-ccitt-checksum-validation-on-each-frame",
      "description": "CRC-16-CCITT checksum validation on each frame",
      "kind": "legacy"
    }
  ],
  "gap_analysis": [
    {
      "clause_id": "FDA-2023-V.B.3",
      "verdict": "missing",
      "quote": "Firmware images and any over-the-air or in-field update artifacts shall be protected with cryptographic authenticity verification using signature schemes based on modern asymmetric cryptography. Integrity-only checks such as CRC or non-cryptographic hashes are insufficient.",
      "reason": "The existing control uses CRC-16-CCITT, which is insufficient as it does not provide cryptographic verification."
    }
  ],
  "cvss_v31": {
    "vector": "CVSS:3.1/AV:P/AC:L/PR:N/UI:N/S:C/C:N/I:H/A:H",
    "base_score": 8.8,
    "severity": "High"
  },
  "residual_risk": "Medium",
  "residual_risk_reason": "Implementing cryptographic validation will significantly reduce the risk of spoofed frames.",
  "proposed_controls": [
    {
      "id": "CTRL:PROPOSED:spi-crypto-validation",
      "description": "Implement cryptographic validation of SPI frames using HMAC-SHA256.",
      "kind": "proposed"
    }
  ],
  "proposed_doc_changes": [
    {
      "doc": "SDS.md",
      "action": "add",
      "item_id": "SDS-SEC-NEW-01",
      "body": "The system shall implement HMAC-SHA256 for cryptographic validation of SPI frames to ensure data integrity and authenticity."
    }
  ],
  "proposed_code_changes": [
    {
      "path": "firmware/safety_mcu/spi_slave.c",
      "line": 50,
      "action": "modify",
      "hunk": "/* Add HMAC-SHA256 validation for incoming SPI frames */\n#include <openssl/hmac.h>\n\nvoid validate_spi_frame(const uint8_t *frame, size_t length) {\n    unsigned char *result;\n    unsigned int result_len;\n    result = HMAC(EVP_sha256(), key, key_len, frame, length, NULL, &result_len);\n    if (!result) {\n        // Handle validation failure\n    }\n}"
    }
  ],
  "priority": "P1",
  "effort_engineer_weeks": 1.5,
  "narrative": "The threat of spoofed SPI frames can lead to false alarms or incorrect patient readings. Implementing HMAC-SHA256 for cryptographic validation of SPI frames will enhance data integrity and authenticity, reducing the risk of spoofed frames."
}

