{
  "threat_id": "P-UI-I01",
  "title": "Patient Data Leak via Screen Capture",
  "stride": "I",
  "assets_affected": [
    "DFD:P-UI"
  ],
  "existing_controls": [],
  "gap_analysis": [
    {
      "clause_id": "FDA-2023-V.B.4",
      "verdict": "missing",
      "quote": "Patient health information (PHI) and sensitive configuration data shall be protected in confidentiality both at rest on the device and during transmission over any network interface. Encryption shall use current, standards-based algorithms and appropriate key management.",
      "reason": "No existing controls address the need for encryption of PHI at rest or in transit."
    },
    {
      "clause_id": "FDA-2023-V.B.6",
      "verdict": "missing",
      "quote": "Bluetooth, Wi-Fi, and other wireless links shall be paired using authenticated, encrypted mechanisms. Just Works or unauthenticated pairing shall not be used for links that carry patient data or control commands. Bluetooth Low Energy shall use LE Secure Connections with numeric comparison or out-of-band authentication.",
      "reason": "No existing controls ensure the use of authenticated and encrypted mechanisms for wireless links."
    },
    {
      "clause_id": "FDA-2023-V.B.2",
      "verdict": "missing",
      "quote": "The device shall implement role-based authorization such that users and services are granted only the minimum privileges required for their function (principle of least privilege). Administrative functions shall be separated from clinical use.",
      "reason": "No existing controls implement role-based authorization or the principle of least privilege."
    },
    {
      "clause_id": "FDA-2023-V.B.9",
      "verdict": "missing",
      "quote": "Debug interfaces (JTAG, UART, SWD) and service ports shall be disabled or protected against unauthorized access in production configurations. Where a service port is required, access shall be gated by strong authentication and shall be auditable.",
      "reason": "No existing controls address the hardening of debug interfaces or service ports."
    },
    {
      "clause_id": "FDA-2023-V.B.8",
      "verdict": "missing",
      "quote": "The device shall log security-relevant events including authentication attempts, privileged operations, configuration changes, and update activities. Logs shall carry tamper-evident properties and be exportable in a machine-readable format.",
      "reason": "No existing controls provide for logging of security-relevant events or tamper-evident logs."
    },
    {
      "clause_id": "AAMI-TIR57-7.1",
      "verdict": "missing",
      "quote": "The manufacturer shall establish a post-market process to monitor emerging vulnerabilities that may affect the device, to assess their applicability, and to communicate mitigations to users and, when appropriate, regulators.",
      "reason": "No existing controls indicate a process for post-market security surveillance or vulnerability monitoring."
    }
  ],
  "cvss_v31": {
    "vector": "CVSS:3.1/AV:P/AC:L/PR:N/UI:R/S:C/C:H/I:L/A:N",
    "base_score": 5.8,
    "severity": "Medium"
  },
  "residual_risk": "Medium",
  "residual_risk_reason": "Implementing encryption and access controls reduces risk but does not eliminate screen capture threats.",
  "proposed_controls": [
    {
      "id": "CTRL:PROPOSED:encrypt_data",
      "description": "Implement encryption for PHI at rest and in transit using AES-256 and TLS 1.2+.",
      "kind": "proposed"
    },
    {
      "id": "CTRL:PROPOSED:role_based_auth",
      "description": "Implement role-based authorization to enforce least privilege access.",
      "kind": "proposed"
    },
    {
      "id": "CTRL:PROPOSED:secure_wireless",
      "description": "Use LE Secure Connections for Bluetooth and WPA2 for Wi-Fi.",
      "kind": "proposed"
    }
  ],
  "proposed_doc_changes": [
    {
      "doc": "SRS.md",
      "action": "add",
      "item_id": "SRS-SEC-NEW-01",
      "body": "The system shall encrypt all patient health information (PHI) at rest and in transit using AES-256 and TLS 1.2+."
    },
    {
      "doc": "SRS.md",
      "action": "add",
      "item_id": "SRS-SEC-NEW-02",
      "body": "The system shall implement role-based authorization to ensure users have the minimum necessary access."
    }
  ],
  "proposed_code_changes": [
    {
      "path": "firmware/app_mcu/ui/ui_manager.c",
      "line": 150,
      "action": "modify",
      "hunk": "if (isScreenMirroringEnabled()) { disableScreenMirroring(); }"
    },
    {
      "path": "firmware/app_mcu/network/tls_config.c",
      "line": 45,
      "action": "modify",
      "hunk": "tls_config_set_protocols(TLS_PROTOCOL_TLSv1_2 | TLS_PROTOCOL_TLSv1_3);"
    }
  ],
  "priority": "P2",
  "effort_engineer_weeks": 2.0,
  "narrative": "The threat of patient data leakage via screen capture is addressed by implementing encryption for data at rest and in transit, role-based access control, and secure wireless communication. These measures aim to protect sensitive information displayed on the UI Manager."
}

