{
  "threat_id": "DF-SPICONFIG-T",
  "title": "Spoofed SPI alarm-threshold commands",
  "stride": "T",
  "assets_affected": [
    "DFD:DF-SPICONFIG"
  ],
  "existing_controls": [
    {
      "id": "CTRL:crc-16-ccitt-per-frame-integrity-check",
      "description": "CRC-16-CCITT per-frame integrity check",
      "kind": "legacy"
    }
  ],
  "gap_analysis": [
    {
      "clause_id": "FDA-2023-V.B.3",
      "verdict": "missing",
      "quote": "Firmware images and any over-the-air or in-field update artifacts shall be protected with cryptographic authenticity verification using signature schemes based on modern asymmetric cryptography. Integrity-only checks such as CRC or non-cryptographic hashes are insufficient.",
      "reason": "The existing control uses CRC-16-CCITT, which is insufficient as it does not meet the modern requirement for cryptographic authenticity verification."
    },
    {
      "clause_id": "AAMI-TIR57-6.3.2",
      "verdict": "partial",
      "quote": "For each security risk that exceeds the acceptable level, the manufacturer shall specify and implement risk-control measures.",
      "reason": "The existing control provides a basic integrity check but does not fully address the need for comprehensive risk-control measures for security risks."
    }
  ],
  "cvss_v31": {
    "vector": "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:C/C:N/I:H/A:N",
    "base_score": 8.6,
    "severity": "High"
  },
  "residual_risk": "Medium",
  "residual_risk_reason": "Implementing cryptographic verification will reduce the risk of spoofed commands significantly.",
  "proposed_controls": [
    {
      "id": "CTRL:PROPOSED:cryptographic-verification",
      "description": "Implement cryptographic verification for SPI commands using HMAC-SHA256.",
      "kind": "proposed"
