{
  "threat_id": "TB-BLE-S",
  "title": "BLE Vitals Spoofing via Fake Device",
  "stride": "S",
  "assets_affected": [
    "DFD:TB-BLE"
  ],
  "existing_controls": [
    {
      "id": "CTRL:physical-protection-of-ble-antenna-shielded-enclosure",
      "description": "Physical protection of BLE antenna (shielded enclosure)",
      "kind": "legacy"
    }
  ],
  "gap_analysis": [
    {
      "clause_id": "FDA-2023-V.B.6",
      "verdict": "missing",
      "quote": "Bluetooth, Wi-Fi, and other wireless links shall be paired using authenticated, encrypted mechanisms. Just Works or unauthenticated pairing shall not be used for links that carry patient data or control commands. Bluetooth Low Energy shall use LE Secure Connections with numeric comparison or out-of-band authentication.",
      "reason": "The existing control does not address the need for authenticated and encrypted pairing mechanisms, which is critical for preventing spoofing attacks."
    },
    {
      "clause_id": "FDA-2023-V.B.7",
      "verdict": "missing",
      "quote": "The device shall implement a secure boot chain such that only cryptographically verified firmware may execute after power-on. Runtime integrity monitoring of critical safety code shall detect and respond to unauthorized modification.",
      "reason": "No existing control addresses secure boot or integrity monitoring, which are essential for ensuring only verified firmware runs."
    },
    {
      "clause_id": "FDA-2023-V.B.4",
      "verdict": "missing",
      "quote": "Patient health information (PHI) and sensitive configuration data shall be protected in confidentiality both at rest on the device and during transmission over any network interface. Encryption shall use current, standards-based algorithms and appropriate key management.",
      "reason": "The existing control does not provide any measures for protecting patient health information during transmission or at rest."
    },
    {
      "clause_id": "FDA-2023-V.B.9",
      "verdict": "missing",
      "quote": "Debug interfaces (JTAG, UART, SWD) and service ports shall be disabled or protected against unauthorized access in production configurations. Where a service port is required, access shall be gated by strong authentication and shall be auditable.",
      "reason": "No existing control addresses the hardening of debug interfaces or service ports, which is necessary to prevent unauthorized access."
    },
    {
      "clause_id": "NIST-800-193-5.2",
      "verdict": "missing",
      "quote": "The platform shall detect corruption of firmware code, firmware data, and critical platform configuration. Detection may occur at boot time, at runtime, or through periodic integrity verification, and shall be reported to a management interface.",
      "reason": "The existing control does not cover the detection of firmware corruption or integrity verification mechanisms."
    },
    {
      "clause_id": "AAMI-TIR57-7.1",
      "verdict": "missing",
      "quote": "The manufacturer shall establish a post-market process to monitor emerging vulnerabilities that may affect the device, to assess their applicability, and to communicate mitigations to users and, when appropriate, regulators.",
      "reason": "No existing control addresses post-market security surveillance or vulnerability monitoring processes."
    }
  ],
  "cvss_v31": {
    "vector": "CVSS:3.1/AV:A/AC:L/PR:N/UI:N/S:C/C:H/I:H/A:H",
    "base_score": 9.6,
    "severity": "Critical"
  },
  "residual_risk": "Medium",
  "residual_risk_reason": "Implementing LE Secure Connections and secure boot will significantly reduce spoofing risk.",
  "proposed_controls": [
    {
      "id": "CTRL:PROPOSED:ble-le-secure-connections",
      "description": "Implement BLE LE Secure Connections with numeric comparison for pairing.",
      "kind": "proposed"
    },
    {
      "id": "CTRL:PROPOSED:secure-boot",
      "description": "Implement secure boot to ensure only cryptographically verified firmware executes.",
      "kind": "proposed"
    }
  ],
  "proposed_doc_changes": [
    {
      "doc": "SRS.md",
      "action": "add",
      "item_id": "SRS-SEC-NEW-01",
      "body": "The device shall use BLE LE Secure Connections with numeric comparison for pairing to prevent unauthorized device connections."
    },
    {
      "doc": "SDS.md",
      "action": "add",
      "item_id": "SDS-SEC-NEW-01",
      "body": "The system shall implement a secure boot process to ensure only cryptographically verified firmware is executed."
    }
  ],
  "proposed_code_changes": [
    {
      "path": "firmware/app_mcu/ble/ble_pairing.c",
      "line": 42,
      "action": "modify",
      "hunk": "/* Implement LE Secure Connections with numeric comparison */"
    },
    {
      "path": "firmware/app_mcu/boot/loader.c",
      "line": 58,
      "action": "modify",
      "hunk": "/* Implement secure boot verification */"
    }
  ],
  "priority": "P0",
  "effort_engineer_weeks": 2.0,
  "narrative": "The threat of BLE vitals spoofing via a fake device is critical due to the use of unauthenticated pairing. Implementing BLE LE Secure Connections and secure boot will mitigate this risk by ensuring authenticated pairing and verified firmware execution."
}

